style.css:
@-moz-document domain("roblox.com") {
:root {
    --rh-bg: #050505;
    --rh-panel: #0d0d0d;
    --rh-panel2: #151515;
    --rh-red: #ff2020;
    --rh-red-dark: #7d0000;
    --rh-text: #f5f5f5;
    --rh-muted: #9b9b9b;
  }

  html, body {
    background: #050505 !important;
    color: var(--rh-text) !important;
  }

  body {
    background:
      radial-gradient(circle at 88% 12%, rgba(255,0,0,.16), transparent 28%),
      radial-gradient(circle at 12% 88%, rgba(120,0,0,.13), transparent 30%),
      #050505 !important;
    min-height: 100vh !important;
  }

  /* CUSTOM IMAGES */
  body::before {
    content: "" !important;
    position: fixed !important;
    left: 8px !important;
    bottom: 0 !important;
    width: 260px !important;
    height: 390px !important;
    background: url("data:image/webp;base64,") center bottom / contain no-repeat !important;
    pointer-events: none !important;
    z-index: 2147483000 !important;
    filter: drop-shadow(0 0 7px #000) !important;
  }

  body::after {
    content: "" !important;
    position: fixed !important;
    right: 18px !important;
    top: 72px !important;
    width: 245px !important;
    height: 175px !important;
    background: url("data:image/webp;base64,") center / contain no-repeat !important;
    pointer-events: none !important;
    z-index: 2147483000 !important;
    filter: drop-shadow(0 0 8px #000) !important;
  }

  /* TOP BAR */
  #header,
  .navbar,
  .rbx-navbar,
  [class*="navbar"],
  [class*="header"] {
    background: rgba(5,5,5,.97) !important;
    border-bottom: 1px solid #242424 !important;
    box-shadow: 0 4px 24px rgba(0,0,0,.65) !important;
  }

  /* LEFT NAVIGATION */
  #navigation,
  .rbx-left-col,
  [class*="sidebar"],
  [class*="side-navigation"] {
    background: #080808 !important;
    border-right: 1px solid #252525 !important;
  }

  /* MAIN AREAS */
  #content,
  .rbx-body,
  .content,
  main,
  [role="main"] {
    background: transparent !important;
    color: var(--rh-text) !important;
  }

  /* PANELS / CARDS */
  .card,
  .game-card,
  .list-item,
  .catalog-item,
  .section,
  .panel,
  [class*="game-card"],
  [class*="GameCard"],
  [class*="thumbnail-card"],
  [class*="tile"] {
    background: linear-gradient(145deg, #161616, #0c0c0c) !important;
    border: 1px solid #282828 !important;
    border-radius: 10px !important;
    box-shadow: 0 7px 25px rgba(0,0,0,.42) !important;
  }

  .card:hover,
  .game-card:hover,
  .catalog-item:hover,
  [class*="game-card"]:hover,
  [class*="GameCard"]:hover,
  [class*="tile"]:hover {
    border-color: rgba(255,32,32,.65) !important;
    box-shadow: 0 0 20px rgba(255,0,0,.12), 0 10px 28px #000 !important;
    transform: translateY(-2px) !important;
    transition: .15s ease !important;
  }

  /* BUTTONS */
  button,
  .btn-primary,
  [class*="btn-primary"],
  [class*="Button-primary"],
  [class*="button-primary"] {
    background: var(--rh-red) !important;
    color: #fff !important;
    border-color: var(--rh-red) !important;
    border-radius: 7px !important;
  }

  button:hover,
  .btn-primary:hover,
  [class*="btn-primary"]:hover,
  [class*="Button-primary"]:hover {
    background: #ff4040 !important;
    box-shadow: 0 0 16px rgba(255,0,0,.25) !important;
  }

  /* TEXT */
  h1,h2,h3,h4,h5,h6,
  p, label, span {
    color: inherit;
  }

  a {
    color: #eee !important;
  }
  a:hover {
    color: var(--rh-red) !important;
  }

  /* INPUTS */
  input, textarea, select, [role="textbox"] {
    background: #0b0b0b !important;
    color: #fff !important;
    border: 1px solid #333 !important;
    border-radius: 7px !important;
  }

  input:focus, textarea:focus, select:focus {
    border-color: var(--rh-red) !important;
    box-shadow: 0 0 0 2px rgba(255,32,32,.16) !important;
  }

  /* MENUS / MODALS */
  [role="dialog"],
  [role="menu"],
  .modal-content,
  .dropdown-menu,
  [class*="popover"],
  [class*="dropdown"] {
    background: #101010 !important;
    color: #fff !important;
    border: 1px solid #333 !important;
    border-radius: 10px !important;
    box-shadow: 0 20px 60px rgba(0,0,0,.75) !important;
  }

  /* SECONDARY TEXT */
  [class*="muted"],
  [class*="secondary"],
  [class*="description"] {
    color: var(--rh-muted) !important;
  }

  /* SCROLLBAR */
  *::-webkit-scrollbar { width: 10px !important; height: 10px !important; }
  *::-webkit-scrollbar-track { background: #050505 !important; }
  *::-webkit-scrollbar-thumb { background: #333 !important; border-radius: 10px !important; }
  *::-webkit-scrollbar-thumb:hover { background: var(--rh-red) !important; }

  ::selection { background: var(--rh-red) !important; color: #fff !important; }

  @media (max-width: 800px) {
    body::before { width: 130px !important; height: 200px !important; left: 0 !important; opacity: .65 !important; }
    body::after { width: 125px !important; height: 95px !important; right: 0 !important; top: 70px !important; opacity: .65 !important; }
  }
}
